'use strict';
// Subject identity is separate from the original practice lesson IDs.
const trackCatalog=(window.ACADEMY.tracks||[]).slice().sort((a,b)=>a.order-b.order);
const trackTopics=trackCatalog.flatMap(track=>track.lessons.map(topic=>({...topic,trackId:track.id})));
const learningPaths=window.ACADEMY.paths||[];
const levels=['beginner','intermediate','advanced'];
let readingTopicId='',readingPathId='';
const getTopic=id=>trackTopics.find(t=>t.id===id);
const getTrack=id=>trackCatalog.find(t=>t.id===id);
const getPath=id=>learningPaths.find(p=>p.id===id);
function topicHref(id,pathId=''){return '#topic='+encodeURIComponent(id)+(pathId?'?path='+encodeURIComponent(pathId):'');}
function topicResource(t){return t.resource||(t.lesson?courseGuide(t.lesson)?.resource:null);}
function topicRow(t,pathId='',index){return `<a class="lesson-row topic-row" href="${topicHref(t.id,pathId)}"><span class="num">${index===undefined?'→':String(index+1).padStart(2,'0')}</span><div class="info"><h3>${esc(t.title)}</h3><p>${esc(t.summary)}</p></div><span class="meta">${esc(t.level)} · ${t.minutes} min</span></a>`;}
function trackCard(t){return `<a class="doc-card track-card" href="#track=${t.id}"><span class="eyebrow">Subject ${String(t.order).padStart(2,'0')} · ${t.lessons.length} topics</span><h3>${esc(t.title)}</h3><p>${esc(t.summary)}</p><div class="card-bottom"><span>Beginner → intermediate → advanced</span><span>Explore →</span></div></a>`;}
function trackHome(){const saved=savedReading();return title('AI Engineering Academy · for SDETs','Understand AI. Use it. Build with it.','Fourteen subject tracks, from first concepts to reliable systems. Every topic explains the idea, shows a testing example, and gives you a concrete way to explore it with Codex or Claude Code.')+`<section class="plain-card first-topic"><span class="eyebrow">${saved?'Your saved reading place':'New to AI? Begin here'}</span><h2>${esc(saved?.title||'Start from zero')}</h2><p>${saved?'Resume the place you explicitly saved, or choose a different subject below.':'Follow a short introduction before choosing a specialty. You only need a browser to read. An assistant is optional for the guided examples.'}</p><div class="actions"><a class="btn" href="${saved?.href||'#start'}">${saved?'Resume reading':'Start from zero'} →</a><a class="btn secondary" href="#path">Choose a learning path</a></div></section><div class="section-head"><h2>Explore every subject</h2><a href="#tracks">Full subject catalog →</a></div><p>Each subject has its own beginner-to-advanced sequence. Choose one when you need it; this catalog is not a completion checklist.</p><div class="grid track-grid">${trackCatalog.map(trackCard).join('')}</div><section class="plain-card"><h2>Your existing course is still here</h2><p>All original lessons, exercises, labs, articles, templates, incidents, bookmarks, and practice records are retained. The original 24 lessons also appear inside their relevant subject tracks.</p><div class="actions"><a href="#legacy">Original 24-lesson sequence →</a><a href="#materials">Search every learning material →</a><a href="#labs">Practice labs →</a></div></section>`;}
function startFromZero(){const p=getPath('zero');return title('Start from zero','Your first step is understanding.','You do not need to build an agent, know a state machine, or produce a diagram. Start with one explanation and a small familiar testing example.')+`<section class="plain-card first-topic"><span class="eyebrow">First session · take it at your pace</span><h2>1. Open the first topic</h2><p>Read “Start here” and the plain-language explanation. Stop at the example and check whether you can follow it. The first page is enough for one session.</p><a class="btn" href="${topicHref(p?.topics[0]||'foundations-orientation','zero')}">Start the first topic →</a><h2>2. Explore it with your assistant · optional</h2><p>Copy the prompt under “Try it with Codex or Claude Code.” It supplies the example. Ask about any unfamiliar word before requesting code. <a href="${linkDoc('docs/ASSISTANT-QUICKSTART.md')}">Open the assistant setup guide →</a></p><h2>3. Check the result and continue</h2><p>Compare it with “What you should see.” Use the bottom <strong>Continue this path</strong> link for the next topic. Save my place is a bookmark; reading does not mark anything complete.</p></section><h2>Your starter path</h2><p>${esc(p?.summary||'An introduction across the core subjects.')} You can pause anywhere, return here, or explore a full subject track.</p>${p?pathTopicList(p):''}<div class="notice">Local mode saves explicit bookmarks and notes in SQLite. The hosted Site saves them in this browser. Use progress export/import to move between them; they do not sync automatically.</div><div class="actions"><a href="#path">Other learning paths →</a><a href="#tracks">All subject tracks →</a><a href="#run">Local setup and account transfer →</a></div>`;}
function trackDirectory(){return title(`${trackCatalog.length} subjects · ${trackTopics.length} topics`,'The whole subject map.','Every major subject has its own visible home, prerequisites, and ordered lessons. Beginner topics explain the language; later topics deepen the same subject.')+`<div class="actions"><a class="btn" href="#start">I am starting from zero →</a><a class="btn secondary" href="#path">Recommended learning paths</a><a href="#legacy">Original lesson sequence</a></div><div class="grid track-grid">${trackCatalog.map(trackCard).join('')}</div>`;}
function subjectTrack(id){const t=getTrack(id);if(!t)return missing();return `<a class="back" href="#tracks">← All subjects</a>`+title(`Subject ${t.order} · ${t.lessons.length} topics`,esc(t.title),esc(t.summary))+`<section class="plain-card"><p>${esc(t.why)}</p><h2>What you will understand</h2><ul>${t.outcomes.map(o=>`<li>${esc(o)}</li>`).join('')}</ul><p><strong>Helpful first:</strong> ${t.prerequisites.length?t.prerequisites.map(id=>`<a href="#track=${id}">${esc(getTrack(id)?.title||id)}</a>`).join(' · '):'No previous AI knowledge. Start at the first topic.'}</p><a class="btn" href="${topicHref(t.lessons[0].id)}">Begin this subject →</a></section>${levels.map(level=>`<section class="track-level"><div class="section-head"><h2>${level[0].toUpperCase()+level.slice(1)}</h2><span>${level==='beginner'?'Understand the language':level==='intermediate'?'Use it deliberately':'Handle harder cases'}</span></div><div class="lesson-list">${t.lessons.filter(l=>l.level===level).map(l=>topicRow(l,'',t.lessons.indexOf(l))).join('')}</div></section>`).join('')}<section class="plain-card"><h2>Choose what to learn after this subject</h2><p>Use a learning path to combine subjects for your work, or return to the full catalog. Your place is saved only when you choose Save my place.</p><div class="actions"><a href="#path">Learning paths →</a><a href="#materials">Search related materials →</a><a href="#tracks">All subjects →</a></div></section>`;}
function pathTopicList(p){return `<div class="lesson-list">${p.topics.map((id,i)=>{const t=getTopic(id);return t?topicRow(t,p.id,i):'';}).join('')}</div>`;}
function recommendedPaths(){return title('Choose by your starting point','Learning paths across subjects.','A path is a curated sequence through the subject tracks. Start from zero is the default. The other paths assume its core ideas; they are alternatives, not extra mandatory work.')+`<div class="grid">${learningPaths.map(p=>`<a class="doc-card" href="#learn=${p.id}"><span class="eyebrow">${esc(p.audience)} · ${p.topics.length} topics</span><h2>${esc(p.title)}</h2><p>${esc(p.summary)}</p><p><strong>Before this:</strong> ${esc(p.prerequisite)}</p><div class="card-bottom"><span>View the sequence</span><span>→</span></div></a>`).join('')}</div><div class="actions"><a href="#tracks">Explore subjects independently →</a><a href="#legacy">Original 24-lesson sequence →</a><a href="${linkDoc('docs/STUDY-PLAN.md')}">Study plan as a document →</a></div>`;}
function selectedPath(id){const p=getPath(id);if(!p)return missing();return `<a class="back" href="#path">← All learning paths</a>`+title(esc(p.audience),esc(p.title),esc(p.summary))+`<p><strong>Before this:</strong> ${esc(p.prerequisite)}</p><p><strong>At the end:</strong> ${esc(p.outcome)}</p>${p.requires?.length?`<p>Preparation paths: ${p.requires.map(id=>`<a href="#learn=${id}">${esc(getPath(id).title)}</a>`).join(' · ')}</p>`:''}<p>Follow this order using “Continue this path” at the end of each topic. Time estimates cover reading and exploring the example, not optional labs. No assessments block reading.</p><a class="btn" href="${topicHref(p.topics[0],id)}">Begin this path →</a>${pathTopicList(p)}<section class="plain-card"><h2>After this path</h2><p>${esc(p.after)}</p><a href="#path">Choose your next path →</a> · <a href="#tracks">Explore a subject in depth →</a></section>`;}
function topicSequence(t,pathId=''){const p=getPath(pathId);if(p?.topics.includes(t.id))return {ids:p.topics,path:p};return {ids:getTrack(t.trackId).lessons.map(x=>x.id),path:null};}
function topicContinue(t,pathId=''){const sequence=topicSequence(t,pathId),i=sequence.ids.indexOf(t.id),next=sequence.ids[i+1],prev=sequence.ids[i-1];return `<section class="lesson-next topic-next" aria-label="Continue learning"><span class="eyebrow">${sequence.path?esc(sequence.path.title):esc(getTrack(t.trackId).title)} · ${i+1} of ${sequence.ids.length}</span><h2>${next?'Continue when the idea makes sense':'You reached the end of this sequence'}</h2><p>${next?'The next topic is ready whenever you are. Practice and additional reading are optional.':'This is a reading milestone, not a mastery claim. Revisit an idea, choose practice, or explore another subject.'}</p><div class="actions">${next?`<a class="btn" href="${topicHref(next,sequence.path?.id)}">${sequence.path?'Continue this path':'Next in this subject'}: ${esc(getTopic(next).title)} →</a>`:'<a class="btn" href="#path">Choose what to learn next →</a>'}${prev?`<a href="${topicHref(prev,sequence.path?.id)}">← Previous topic</a>`:''}<a href="${sequence.path?'#learn='+sequence.path.id:'#track='+t.trackId}">View this sequence</a></div></section>`;}
function subjectTeaching(t){let text=A.documents[t.file].text;if(t.lesson){text=text.replace(/^# \d+ · /,'# ').replace(/\b(?:Proceed|Continue) to (\[[^\]]+\]\([^)]+\))([^\n.]*\.)/g,'Related reading: $1$2');}return markdown(text,t.file);}
function topicPage(id,pathId=''){const t=getTopic(id);if(!t||!A.documents[t.file])return missing();const track=getTrack(t.trackId),sequence=topicSequence(t,pathId),p=sequence.path,l=lessons.find(l=>l.id===t.lesson),g=l?courseGuide(l.id):null,resource=topicResource(t),notePath=l?.file||t.file;readingTopicId=t.id;readingPathId=p?.id||'';return `<div class="topic-breadcrumb"><a href="#tracks">Subjects</a><span> / </span><a href="#track=${track.id}">${esc(track.title)}</a><span> / ${esc(t.level)}</span></div><div class="topic-position"><span class="eyebrow">${p?'Path: '+esc(p.title):'Subject: '+esc(track.title)} · ${t.minutes} min estimate</span><button class="btn secondary small" id="save-topic-reading" data-id="${t.id}" data-path="${p?.id||''}">${state.topicReading===t.id?'✓ Resume here':'Save my place'}</button></div><div class="actions lesson-jumps"><a href="${topicHref(t.id,p?.id)}&section=start-here">Start here</a><a href="${topicHref(t.id,p?.id)}&section=try-it-with-codex-or-claude-code">Assistant how-to</a><a href="${topicHref(t.id,p?.id)}&section=topic-materials">Related materials</a>${l?`<a href="${topicHref(t.id,p?.id)}&section=original-lesson">Original lesson & exercises</a>`:''}</div><div class="reading-layout"><article class="reading"><section class="beginner-guide">${subjectTeaching(t)}</section>${topicContinue(t,p?.id)}<section class="topic-materials" id="topic-materials"><h2>Selected reading and related materials</h2><p>The introduction above is self-contained. Open only the extra reading that helps your current question, then return here.</p>${resource?`<div class="plain-card guide-source">${guideResource(resource)}</div>`:''}${materialLinks([...new Set([...(t.materials||[]),...(g?.materials||[])])])}</section>${l?`<section id="original-lesson"><h2>Retained original lesson and optional exercises</h2><p>This is the complete original explanation. Independent implementation comes after the concept makes sense. The exercise workspaces preserve your attempts and progressive hints.</p>${lessonOriginal(l)}</section>${topicContinue(t,p?.id)}`:''}</article><aside class="reading-side"><div class="side-block"><h3>You are here</h3><a href="#track=${track.id}">${esc(track.title)} track →</a>${p?`<a href="#learn=${p.id}">${esc(p.title)} path →</a>`:''}<p>${esc(t.summary)}</p><h3>Helpful before this topic</h3>${t.prerequisites?.length?t.prerequisites.map(id=>`<a class="practice-link" href="${topicHref(id,p?.topics.includes(id)?p.id:'')}">${esc(getTopic(id)?.title||id)} →</a>`).join(''):'<p>Start here without previous knowledge of this subject.</p>'}<a class="practice-link" href="${linkDoc('docs/ASSISTANT-QUICKSTART.md')}">How to use Codex or Claude Code →</a></div><div class="side-block"><h3>This subject</h3>${track.lessons.map(x=>`<a class="practice-link" href="${topicHref(x.id)}" ${x.id===id?'aria-current="page"':''}>${x.id===id?'● ':''}${esc(x.title)}</a>`).join('')}</div>${l?practiceLinks(l)+quizHTML(l):''}<div class="side-block"><h3>Your notes · optional</h3><textarea id="notes" data-path="${esc(notePath)}" aria-label="Your notes about this topic" placeholder="A question or observation…">${esc(state.notes[notePath]||'')}</textarea><span id="note-status" class="results-count" aria-live="polite"></span><button class="btn secondary" id="download-doc" data-path="${esc(t.file)}">Download this reading ↓</button>${l?`<button class="btn secondary" id="mark-done" data-id="${l.id}">${done(l.id)?'✓ Completed · undo':'Mark original lesson complete'}</button><a href="#lesson=${l.id}">Original lesson ${l.id} route →</a>`:''}<p>Reading and bookmarks never mark completion. ${esc(storageSummary())}</p></div></aside></div>`;}
function subjectSidebar(context){const route=context.route.split('?')[0],active=route.startsWith('track=')?getTrack(route.slice(6)):route.startsWith('topic=')?getTrack(getTopic(route.slice(6))?.trackId):null;const legacyTopic=context.lesson?trackTopics.find(t=>t.lesson===context.lesson.id):null;const selected=active||getTrack(legacyTopic?.trackId);let count=0;const html=trackCatalog.map(t=>{const trackMatch=sidebarMatches(t.title,t.summary,t.id),topics=t.lessons.filter(x=>!sidebarQuery||trackMatch||sidebarMatches(x.title,x.summary,...x.keywords));if(!topics.length)return '';count+=1+topics.length;const show=!!sidebarQuery||selected?.id===t.id;return `<div class="nav-subject"><a class="nav-page nav-track ${selected?.id===t.id?'active':''}" data-track="${t.id}" href="#track=${t.id}" ${route==='track='+t.id?'aria-current="page"':''}><span class="icon" aria-hidden="true">${String(t.order).padStart(2,'0')}</span><span>${esc(t.title)}</span><span class="track-count">${t.lessons.length}</span></a>${show?`<div class="nav-topics">${topics.map(x=>`<a class="nav-topic ${route==='topic='+x.id?'active':''}" data-topic="${x.id}" href="${topicHref(x.id)}" ${route==='topic='+x.id?'aria-current="page"':''}><small>${esc(x.level)}</small><span>${esc(x.title)}</span></a>`).join('')}</div>`:''}</div>`;}).join('');return {html:html?`<section class="nav-group"><h2>Subject tracks</h2>${html}</section>`:'',count,selected};}
